# Check if same user question gets same response
from collections import defaultdict

question_to_responses = defaultdict(list)
for q, r in zip(user_lines, assistant_lines):
    question_to_responses[q].append(r)

# Find questions that appear multiple times
for q, responses in question_to_responses.items():
    if len(responses) > 1:
        print(f"Question: {q}")
        for i, r in enumerate(responses):
            print(f"  Response {i+1}: {r}")
        print()
        break  # Just show first one for now

# Let me check if there's a pattern - maybe the assistant responses encode something
# Let me look at the first character of each word in a response
def words_to_first_chars(response):
    return ''.join(w[0] for w in response.split())

# Check a few responses
for i in range(10):
    print(f"Response {i}: {assistant_lines[i]}")
    print(f"  First chars: {words_to_first_chars(assistant_lines[i])}")
    print()

# Find all occurrences of "What chess opening would you suggest for a beginner?"
target_question = "What chess opening would you suggest for a beginner?"
occurrences = []
for i, line in enumerate(lines):
    if line.startswith('user:') and line[len('user: '):] == target_question:
        occurrences.append(i)

print(f"Found {len(occurrences)} occurrences")
for idx, line_num in enumerate(occurrences[:5]):
    print(f"Occurrence {idx+1} at line {line_num}: {lines[line_num]}")
    print(f"  Response: {lines[line_num+1]}")
